#include <bits/stdc++.h>
using namespace std;

class Solution {int ans=0;pair<int,int> dfs(TreeNode* p){if(!p)return {0,0};auto a=dfs(p->left),b=dfs(p->right);int sum=a.first+b.first+p->val,cnt=a.second+b.second+1;if(sum/cnt==p->val)++ans;return {sum,cnt};}public:int averageOfSubtree(TreeNode* root){dfs(root);return ans;} };
